/**
 * `telamonjs add` — adds ready-made modules to an app generated by `telamonjs create`.
 */
import { Command } from 'commander'
import chalk from 'chalk'
import { ADMIN_MODULES, AdminKitError, addAdmin, printAddAdminResult } from './admin.js'

export const addCommand = new Command('add').description('Add ready-made modules to an app generated by `telamonjs create`')

addCommand
  .command('admin')
  .description(
    `Scaffold an admin-kit module (${ADMIN_MODULES.join(', ')}): Prisma model, API, permissions, menu entry, i18n messages and admin page. Never migrates`
  )
  .argument('<module>', `Module to add: ${ADMIN_MODULES.join(' | ')}`)
  .option('--dry-run', 'List the files it would create or modify, write nothing')
  .option('--cwd <dir>', 'App root (default: the current directory)')
  .action((module: string, options: { dryRun?: boolean; cwd?: string }) => {
    try {
      printAddAdminResult(module, addAdmin(module, options), Boolean(options.dryRun))
    } catch (error) {
      if (!(error instanceof AdminKitError)) throw error
      console.error(chalk.red(`\n${error.message}\n`))
      process.exit(1)
    }
  })
